PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?service) AS ?count)
WHERE {
  # Find all primary services (not replicas)
  ?service rdf:type/rdfs:subClassOf* ex:Service .
  FILTER NOT EXISTS { ?service ex:replicaOf ?other . }

  # Find all nodes in the replica group of this service
  # (the service itself plus all nodes connected via replicaOf transitively)
  ?service (ex:replicaOf | ^ex:replicaOf)* ?groupMember .

  # Get all regions where replica group members are deployed
  ?groupMember ex:deployedIn ?region .

  # Collect all regions in the footprint
  BIND(COLLECT(DISTINCT ?region) AS ?footprint)

  # Check if service is lost: footprint contains only reg-2
  FILTER (
    # The service is lost if all its replicas are in reg-2
    NOT EXISTS {
      ?service (ex:replicaOf | ^ex:replicaOf)* ?member .
      ?member ex:deployedIn ?r .
      FILTER (?r != ex:reg-2)
    }
  )

  # Now check if this service is down:
  # Either it's lost, or it depends on something that's lost
  {
    # Case 1: This service itself is lost (already filtered above)
  }
  UNION
  {
    # Case 2: This service depends on a lost node
    ?service ex:dependsOn+ ?depNode .

    # Check if depNode is lost
    ?depNode (ex:replicaOf | ^ex:replicaOf)* ?depGroupMember .
    ?depGroupMember ex:deployedIn ?depRegion .

    FILTER NOT EXISTS {
      ?depNode (ex:replicaOf | ^ex:replicaOf)* ?depMember .
      ?depMember ex:deployedIn ?depR .
      FILTER (?depR != ex:reg-2)
    }
  }
}
